+	resolvedInstallation toolchain.Installation
+	installationRootArg  string
+	installationPath     string
+	installationSet      bool
+	runnerBuild          string
+	runnerBuildSet       bool
+	privateCommands      privateCommands
+	privateCommandsSet   bool
