+func TestRunChoiceExplorationDivergencePoliciesAndInspection(t *testing.T) {
+	for _, policy := range []FailurePolicy{PolicyFirst, PolicyBudget, PolicyAll} {
+		t.Run(string(policy), func(t *testing.T) {
