			os.Exit(13)
		}
		os.Exit(0)
	case "world-record":
		core, err := world.New(world.Config{Seed: 9, Limits: world.Limits{MaxRequests: 10, MaxEvents: 10, MaxQueuedEvents: 10, MaxTransitions: 10, MaxPayloadBytes: 1024, MaxStringBytes: 64}})
		if err != nil {
